package workerclient

// normalize_test.go — NormalizeURL's differential (the reference's own
// outputs at the pinned rev, byte-compared) + the entry builders + the
// hand-rolled uuid4's shape law.

import (
	"strings"
	"testing"

	"github.com/assadigit/second-brain-project/internal/storage"
)

// generated by running the unmodified reference's
// CloudflareSync.normalize_url at rev 98f4fc7 (the SESSION-014 venv
// run; static facts, byte-compared).
var normalizeVectors = []struct{ raw, want string }{
	{"https://Example.COM/Path/", "https://example.com/Path"},
	{"https://x.com/status/123 ", "https://x.com/status/123"},
	{"https://twitter.com/user/status/1", "https://x.com/user/status/1"},
	{"https://example.com/page?utm_source=x#frag", "https://example.com/page"},
	{"https://example.com/path ends with dot.", "https://example.com/path ends with dot"},
	{"https://example.com/x);", "https://example.com/x"},
	{"https://example.com//", "https://example.com"},
	{"https://EXAMPLE.com/UPPER/Path", "https://example.com/UPPER/Path"},
	{"https://example.com/a/twitter.com/b", "https://example.com/a/x.com/b"},
	{"http://LOCALHOST:8080/x", "http://localhost:8080/x"},
	{"https://example.com/path?", "https://example.com/path"},
	{"https://example.com/path#", "https://example.com/path"},
	{"  https://example.com/spaces  ", "https://example.com/spaces"},
	{"https://example.com/trailing...,,);;;", "https://example.com/trailing"},
	{"mailto:someone@example.com", "mailto:someone@example.com"},
	{"https://", "https://"},
	{"https://only-domain.COM", "https://only-domain.com"},
}

func TestNormalizeURLDifferential(t *testing.T) {
	for _, c := range normalizeVectors {
		if got := NormalizeURL(c.raw); got != c.want {
			t.Errorf("NormalizeURL(%q) = %q, want %q", c.raw, got, c.want)
		}
	}
}

func TestBuildVaultMirrorEntries(t *testing.T) {
	idx := storage.NewOrderedMap()
	info := storage.NewOrderedMap()
	info.Set("path", "a/b.md")
	info.Set("category", "Tools")
	info.Set("title", "B")
	info.Set("first_processed", "2026-01-01T00:00:00")
	idx.Set("https://x.test/", info)
	info2 := storage.NewOrderedMap()
	info2.Set("path", "c.md")
	idx.Set("https://y.test/", info2)

	entries := BuildVaultMirrorEntries(idx)
	if len(entries) != 2 {
		t.Fatalf("entries = %d", len(entries))
	}
	e0 := entries[0].(*storage.OrderedMap)
	if got, _ := e0.Get("url_normalized"); got != "https://x.test/" {
		t.Errorf("url = %v", got)
	}
	if got, _ := e0.Get("status"); got != "in_vault" {
		t.Errorf("status = %v", got)
	}
	// last_updated falls back to now-ISO (non-empty, +00:00 aware)
	if got, _ := e0.Get("last_updated_at"); !strings.Contains(got.(string), "+00:00") &&
		len(got.(string)) != 19 {
		t.Errorf("last_updated_at = %v", got)
	}
	// the key order (the wire bytes): url, path, category, title,
	// status, first_processed_at, last_updated_at
	keys := e0.Keys()
	want := []string{"url_normalized", "vault_path", "category", "title",
		"status", "first_processed_at", "last_updated_at"}
	if strings.Join(keys, "|") != strings.Join(want, "|") {
		t.Errorf("keys = %v", keys)
	}
	// insertion order preserved (x before y)
	e1 := entries[1].(*storage.OrderedMap)
	if got, _ := e1.Get("url_normalized"); got != "https://y.test/" {
		t.Errorf("second url = %v", got)
	}
	// hostile shapes never panic
	if got := BuildVaultMirrorEntries(nil); got != nil {
		t.Errorf("nil index = %v", got)
	}
	if got := BuildVaultMirrorEntries("junk"); got != nil {
		t.Errorf("junk index = %v", got)
	}
}

func TestBuildDecommissionEvents(t *testing.T) {
	events := BuildDecommissionEvents([]DecommissionEventRow{
		{URL: "https://gone.test/", Reason: "404"},
		{URL: "https://other.test/", Reason: ""},
	})
	if len(events) != 2 {
		t.Fatalf("events = %d", len(events))
	}
	e0 := events[0].(*storage.OrderedMap)
	if got, _ := e0.Get("url_normalized"); got != "https://gone.test/" {
		t.Errorf("url = %v", got)
	}
	if got, _ := e0.Get("reason"); got != "404" {
		t.Errorf("reason = %v", got)
	}
	// the missing reason defaults to '404' (the reference's .get law)
	e1 := events[1].(*storage.OrderedMap)
	if got, _ := e1.Get("reason"); got != "404" {
		t.Errorf("default reason = %v", got)
	}
	if got, _ := e1.Get("decommissioned_at"); !strings.Contains(got.(string), "T") {
		t.Errorf("decommissioned_at = %v", got)
	}
}

func TestNewSyncIDShape(t *testing.T) {
	seen := map[string]bool{}
	for i := 0; i < 100; i++ {
		id := newSyncID()
		if len(id) != 36 {
			t.Fatalf("id = %q (not a uuid shape)", id)
		}
		// the v4 version nibble + the RFC-4122 variant bits
		if id[14] != '4' {
			t.Fatalf("id = %q (version nibble %c)", id, id[14])
		}
		switch id[19] {
		case '8', '9', 'a', 'b':
		default:
			t.Fatalf("id = %q (variant bits %c)", id, id[19])
		}
		if seen[id] {
			t.Fatalf("duplicate id %q", id)
		}
		seen[id] = true
	}
}

func TestNowISOShape(t *testing.T) {
	s := nowISO()
	// datetime.now(timezone.utc).isoformat(): aware +00:00, T-separator
	if !strings.HasSuffix(s, "+00:00") || !strings.Contains(s, "T") {
		t.Errorf("nowISO = %q", s)
	}
}

func TestUnpairClearsTheConfig(t *testing.T) {
	cfg := map[string]any{
		"cloudflare_install_id":    "id",
		"cloudflare_shared_secret": "sec",
		"cloudflare_enabled":       true,
	}
	s := NewSync(cfg)
	s.Unpair()
	if cfg["cloudflare_install_id"] != "" ||
		cfg["cloudflare_shared_secret"] != "" ||
		cfg["cloudflare_enabled"] != false {
		t.Errorf("unpair left state: %v", cfg)
	}
}
